const DASHBOARD_CSS = `
  :root{
    --bg:#F7F6F1; --bg2:#FFFFFF; --card:#FFFFFF; --card-hi:#FBF3E3;
    --border:rgba(197,140,34,0.18); --border-soft:rgba(20,33,61,0.09);
    --gold:#E0932A; --gold-dim:#B9761C; --teal:#0FA89A; --coral:#E1544A; --violet:#6C63C7;
    --text:#1A2233; --text-mid:#5B6478; --text-dim:#8891A0;
    --navy:#0F2A6B; --navy-dark:#0A1D4D;
    --topbar-h:66px;
  }
  *{box-sizing:border-box; margin:0; padding:0;}
  html{scroll-behavior:smooth;}
  body{
    background:var(--bg); color:var(--text);
    font-family:'Noto Sans Thai',sans-serif; font-weight:400; line-height:1.55;
    background-image:
      radial-gradient(circle at 15% 8%, rgba(224,147,42,0.07), transparent 40%),
      radial-gradient(circle at 85% 0%, rgba(15,168,154,0.06), transparent 35%);
  }
  .num{font-family:'Noto Sans Thai',sans-serif;}
  h1,h2,h3,.disp{font-family:'Noto Sans Thai',sans-serif;}

  /* ---- Top masthead bar (logo + filters combined) ---- */
  .topbar{
    position:sticky; top:0; z-index:70;
    background:#fff;
    border-bottom:1px solid var(--border-soft);
    padding:13px 20px; display:flex; align-items:center; gap:14px; flex-wrap:wrap;
    box-shadow:0 1px 2px rgba(20,33,61,0.03);
  }
  .topbar::before{
    content:''; position:absolute; top:0; left:0; right:0; height:4px;
    background:linear-gradient(90deg, var(--gold), var(--teal));
  }
  .topbar img{ height:38px; width:auto; display:block; flex-shrink:0; }
  .filter-cluster{
    flex:1; display:flex; align-items:center; gap:14px; flex-wrap:wrap;
    background:linear-gradient(135deg, rgba(224,147,42,0.10), rgba(15,168,154,0.08));
    border:1px solid var(--border);
    border-radius:18px; padding:9px 18px;
    box-shadow:inset 0 1px 0 rgba(255,255,255,0.6), 0 1px 3px rgba(20,33,61,0.04);
  }
  .topbar .flabel{font-family:'Noto Sans Thai'; font-weight:600; font-size:11px; color:var(--gold-dim); text-transform:uppercase; letter-spacing:0.05em; display:flex; align-items:center; gap:6px;}

  .app-shell{ display:flex; align-items:stretch; min-height:calc(100vh - var(--topbar-h)); }

  .sidebar{
    width:230px; flex-shrink:0;
    position:sticky; top:var(--topbar-h); align-self:flex-start; height:calc(100vh - var(--topbar-h)); overflow-y:auto;
    background:linear-gradient(180deg, #363C56, #2C3148);
    padding:22px 14px; display:flex; flex-direction:column; gap:18px;
    scrollbar-width:thin;
  }
  .sidenav{ display:flex; flex-direction:column; gap:2px; }
  .sidenav a{
    position:relative; color:#B7BCCC; text-decoration:none; font-size:12px; line-height:1.35;
    padding:10px 14px; border-radius:9px; transition:all .15s ease;
    font-family:'Noto Sans Thai'; letter-spacing:0.01em; display:block;
  }
  .sidenav a:hover{background:rgba(255,255,255,0.08); color:#fff;}
  .sidenav a.active{
    background:rgba(108,99,199,0.28); color:#fff; font-weight:500;
    box-shadow:inset 3px 0 0 var(--violet);
  }

  .main-col{ flex:1; min-width:0; display:flex; flex-direction:column; }

  /* ---- Filter groups (now inside topbar) ---- */
  .fgroup{display:flex; flex-direction:column; gap:3px;}
  .fgroup span{font-size:10.5px; color:var(--text-dim); font-family:'Noto Sans Thai';}
  .fgroup select{
    font-family:'Noto Sans Thai',sans-serif; font-size:12.5px; color:var(--text);
    background:#fff; border:1px solid var(--border-soft); border-radius:8px; padding:6px 10px;
    min-width:150px; cursor:pointer;
  }
  .fgroup select:focus{outline:2px solid var(--gold); outline-offset:1px;}
  #fReset{
    font-family:'Noto Sans Thai'; font-size:11.5px; color:var(--coral); background:none;
    border:1px solid rgba(225,84,74,0.35); border-radius:20px; padding:6px 14px; cursor:pointer;
    transition:all .15s ease; align-self:flex-end;
  }
  #fReset:hover{background:rgba(225,84,74,0.08);}
  .fcount{
    margin-left:auto; font-family:'Noto Sans Thai'; font-size:12px; color:var(--text-mid);
    background:#fff; border:1px solid var(--border-soft); border-radius:20px; padding:7px 14px;
    white-space:nowrap;
  }
  .fcount b{color:var(--gold-dim); font-weight:700;}

  .lang-toggle{
    display:flex; align-items:center; background:#F0F1F4; border:1px solid var(--border-soft);
    border-radius:22px; padding:4px; gap:1px; flex-shrink:0; margin-left:10px;
  }
  .lang-btn{
    font-family:'Noto Sans Thai'; font-size:12.5px; font-weight:700; letter-spacing:0.02em;
    padding:8px 18px; border-radius:18px;
    border:none; background:none; color:var(--text-dim); cursor:pointer;
    transition:background .2s ease, color .2s ease, box-shadow .2s ease;
  }
  .lang-btn:hover{ color:var(--text); }
  .lang-btn.active{
    background:#fff; color:var(--text); font-weight:800;
    box-shadow:0 1px 4px rgba(20,33,61,0.12), 0 0 0 1px rgba(20,33,61,0.03);
  }

  .scale-toggle{
    display:flex; align-items:center; background:#F0F1F4; border:1px solid var(--border-soft);
    border-radius:22px; padding:4px; gap:1px; flex-shrink:0;
  }
  .scale-btn{
    font-family:'Noto Sans Thai'; font-size:11.5px; font-weight:700; letter-spacing:0.02em;
    padding:6px 14px; border-radius:18px;
    border:none; background:none; color:var(--text-dim); cursor:pointer;
    transition:background .2s ease, color .2s ease, box-shadow .2s ease;
  }
  .scale-btn:hover{ color:var(--text); }
  .scale-btn.active{
    background:#fff; color:var(--text); font-weight:800;
    box-shadow:0 1px 4px rgba(20,33,61,0.12), 0 0 0 1px rgba(20,33,61,0.03);
  }
  .stat-chip{
    display:inline-flex; align-items:center; gap:6px; font-family:'Noto Sans Thai'; font-size:12px;
    background:#fff; border:1px solid var(--border-soft); border-radius:20px; padding:7px 14px; color:var(--text-mid);
  }
  .stat-chip b{ color:var(--text); font-weight:800; }
  .scatter-note{ font-size:11px; color:var(--text-dim); margin-top:6px; }

  .hero{position:relative; overflow:hidden; padding:48px 32px 40px; border-bottom:1px solid var(--border-soft);}
  .hero-grid{
    position:absolute; inset:0; opacity:0.6;
    background-image:radial-gradient(circle, rgba(224,147,42,0.16) 1px, transparent 1px);
    background-size:26px 26px; mask-image:linear-gradient(to bottom, black, transparent 85%);
  }
  .hero-inner{position:relative; max-width:1180px; margin:0 auto;}
  .eyebrow{
    display:inline-flex; align-items:center; gap:8px; font-family:'Noto Sans Thai'; font-size:12px; color:var(--gold);
    letter-spacing:0.08em; text-transform:uppercase; border:1px solid var(--border); padding:5px 12px; border-radius:20px; margin-bottom:22px;
  }
  .eyebrow::before{content:''; width:6px; height:6px; border-radius:50%; background:var(--teal); box-shadow:0 0 8px var(--teal);}
  .hero h1{ font-size:clamp(26px,3.4vw,42px); font-weight:700; letter-spacing:-0.01em; max-width:1120px; line-height:1.28; }
  .hero h1 em{font-style:normal; color:var(--gold); display:block; margin-top:4px;}
  .hero p{color:var(--text-mid); max-width:640px; margin-top:16px; font-size:15px;}
  .hero p.hero-hint{color:var(--text-dim); font-size:13px; margin-top:10px;}

  .kpi-row{display:grid; grid-template-columns:repeat(5,1fr); gap:14px; margin-top:56px;}
  .kpi{ background:var(--card); border:1px solid var(--border-soft); border-radius:12px; padding:20px 18px; position:relative; overflow:hidden; box-shadow:0 2px 10px rgba(20,33,61,0.05); }
  .kpi::after{ content:''; position:absolute; bottom:0; left:0; height:2px; width:100%; background:linear-gradient(90deg, var(--gold), transparent); }
  .kpi .label{font-size:11.5px; color:var(--text-dim); font-family:'Noto Sans Thai'; text-transform:uppercase; letter-spacing:0.04em;}
  .kpi .value{font-family:'Noto Sans Thai'; font-weight:700; font-size:26px; margin-top:8px; color:var(--text);}
  .kpi .value .unit{font-size:13px; font-weight:400; color:var(--text-mid); margin-left:3px;}
  .kpi .sub{font-size:11.5px; color:var(--teal); margin-top:4px; font-family:'Noto Sans Thai';}

  main{max-width:1180px; margin:0 auto; padding:56px 32px;}
  section{margin-bottom:76px; scroll-margin-top:150px;}
  .sec-head{display:flex; align-items:baseline; gap:12px; margin-bottom:24px; flex-wrap:wrap;}
  .sec-num{font-family:'Noto Sans Thai'; font-size:12px; color:var(--gold-dim); border:1px solid var(--border); padding:3px 9px; border-radius:6px;}
  .sec-head h2{font-size:22px; font-weight:600;}
  .sec-desc{color:var(--text-dim); font-size:13px; margin-top:4px; max-width:680px;}

  .grid2{display:grid; grid-template-columns:minmax(0,1.15fr) minmax(0,0.85fr); gap:18px;}
  .grid2-even{display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px;}
  .grid3{display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px;}
  .grid4{display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px;}
  .circle-row{display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px;}

  .card{ background:var(--card); border:1px solid var(--border-soft); border-radius:14px; padding:22px 24px; min-width:0; box-shadow:0 2px 14px rgba(20,33,61,0.05); display:flex; flex-direction:column; }
  .card h3{font-size:14px; font-weight:600; color:var(--text); margin-bottom:2px;}
  .card .hint{font-size:11.5px; color:var(--text-dim); margin-bottom:14px; font-family:'Noto Sans Thai';}
  .chart-wrap{position:relative; flex:none; width:100%;}

  .dmi-hero{
    display:grid; grid-template-columns:0.9fr 1.1fr; gap:28px; align-items:center;
    background:linear-gradient(135deg, var(--card-hi), var(--card)); border:1px solid var(--border); border-radius:18px; padding:32px;
    box-shadow:0 4px 20px rgba(20,33,61,0.06);
  }
  .gauge-box{display:flex; flex-direction:column; align-items:center; text-align:center;}
  .level-legend{display:flex; flex-wrap:wrap; gap:8px 16px; margin-bottom:16px;}
  .level-legend .item{display:flex; align-items:center; gap:6px; font-size:11px; font-family:'Noto Sans Thai'; color:var(--text-mid);}
  .level-legend .dot{width:9px; height:9px; border-radius:3px; flex-shrink:0;}
  .gauge-score{font-family:'Noto Sans Thai'; font-weight:800; font-size:48px; color:var(--gold-dim); margin-top:-108px;}
  .gauge-score .of{font-size:18px; color:var(--text-dim); font-weight:400;}
  .gauge-label{font-size:12px; color:var(--text-mid); font-family:'Noto Sans Thai'; margin-top:6px; letter-spacing:0.03em;}
  .dmi-dims{display:flex; flex-direction:column; gap:10px; margin-top:18px; width:100%; max-width:340px;}
  .dmi-dim-row{display:flex; align-items:center; gap:10px;}
  .dmi-dim-row .name{width:130px; font-size:11.5px; color:var(--text-mid); text-align:right; flex-shrink:0;}
  .dmi-dim-row .bar-track{flex:1; height:7px; background:rgba(20,33,61,0.08); border-radius:4px; overflow:hidden;}
  .dmi-dim-row .bar-fill{height:100%; border-radius:4px;}
  .dmi-dim-row .v{width:32px; font-family:'Noto Sans Thai'; font-size:11.5px; color:var(--text);}

  .barlist{display:flex; flex-direction:column; gap:12px;}
  .barlist-row .top{display:flex; justify-content:space-between; font-size:12.5px; margin-bottom:5px;}
  .barlist-row .top .name{color:var(--text-mid);}
  .barlist-row .top .pct{font-family:'Noto Sans Thai'; color:var(--text); font-weight:500;}
  .barlist-row .track{height:8px; background:rgba(20,33,61,0.07); border-radius:5px; overflow:hidden;}
  .barlist-row .fill{height:100%; border-radius:5px;}
  .fill-gold{background:linear-gradient(90deg,var(--gold-dim),var(--gold));}
  .fill-teal{background:linear-gradient(90deg,#0C7B70,var(--teal));}
  .fill-coral{background:linear-gradient(90deg,#A63D36,var(--coral));}
  .fill-violet{background:linear-gradient(90deg,#4D45A3,var(--violet));}

  .statpair{display:flex; gap:16px; flex:1; align-items:center;}
  .statpair .stat{flex:1; text-align:center; display:flex; flex-direction:column; align-items:center; justify-content:center;}
  .ring-wrap{position:relative; width:150px; height:150px; margin:0 auto 10px;}
  .ring-val{position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-family:'Noto Sans Thai'; font-weight:700; font-size:26px; color:var(--text);}
  .ring-caption{font-size:12px; color:var(--text-mid); font-family:'Noto Sans Thai'; text-align:center;}

  footer{ border-top:1px solid var(--border-soft); padding:28px 32px; text-align:center; color:var(--text-dim); font-size:11.5px; font-family:'Noto Sans Thai'; }
  footer a{color:var(--gold-dim);}

  .nodata{ display:flex; align-items:center; justify-content:center; height:100%; color:var(--text-dim); font-size:12px; font-family:'Noto Sans Thai'; text-align:center; padding:20px; }

  .insight-callout{
    margin-top:12px; padding:11px 14px;
    background:var(--card-hi);
    border-radius:10px;
    display:flex; align-items:flex-start; gap:11px;
  }
  .insight-callout .ic-icon{
    width:26px; height:26px; border-radius:50%; flex-shrink:0;
    display:flex; align-items:center; justify-content:center;
    font-size:12px; margin-top:1px;
  }
  .insight-callout .ic-body{ flex:1; min-width:0; }
  .insight-callout .support b{ font-weight:700; }
  .insight-callout .note{ font-size:11px; color:var(--text-dim); line-height:1.6; margin-top:8px; }

  .yoy-box{
    margin-top:14px; padding:12px 14px; background:var(--card-hi); border:1px dashed var(--border);
    border-radius:10px; font-size:11.5px;
  }
  .yoy-box .yoy-title{ font-family:'Noto Sans Thai'; color:var(--gold-dim); font-size:10.5px; text-transform:uppercase; letter-spacing:0.03em; margin-bottom:10px; }
  .yoy-head{ display:flex; align-items:center; gap:8px; margin-bottom:8px; padding-bottom:8px; border-bottom:1px solid var(--border); }
  .yoy-head .yoy-label{ flex:1; min-width:120px; }
  .yoy-head .yoy-vals{ display:flex; align-items:center; gap:6px; }
  .yoy-head .yoy-yr-old, .yoy-head .yoy-yr-new{
    font-family:'Noto Sans Thai'; font-weight:700; font-size:12px; width:58px; text-align:right;
    padding:3px 8px; border-radius:6px;
  }
  .yoy-head .yoy-yr-old{ color:var(--text-mid); background:rgba(20,33,61,0.06); }
  .yoy-head .yoy-yr-new{ color:var(--gold-dim); background:rgba(224,147,42,0.14); }
  .yoy-head .yoy-arrow{ color:var(--text-dim); width:14px; text-align:center; }
  .yoy-row{ display:flex; align-items:center; gap:8px; margin-bottom:6px; flex-wrap:wrap; }
  .yoy-row:last-child{ margin-bottom:0; }
  .yoy-row .yoy-label{ flex:1; min-width:120px; color:var(--text-mid); }
  .yoy-row .yoy-vals{ display:flex; align-items:center; gap:6px; font-family:'Noto Sans Thai'; font-weight:500; white-space:nowrap; }
  .yoy-row .yoy-old{ color:var(--text-dim); width:58px; text-align:right; display:inline-block; }
  .yoy-row .yoy-arrow{ color:var(--text-dim); width:14px; text-align:center; display:inline-block; }
  .yoy-row .yoy-new{ color:var(--text); font-weight:700; width:58px; text-align:right; display:inline-block; }
  .yoy-row .yoy-new.up{ color:var(--teal); }
  .yoy-row .yoy-new.down{ color:var(--coral); }

  /* ---- Household e-Commerce Value infographic (static, report-sourced) ---- */
  .value-section{ margin-bottom:44px; }
  .value-title{ font-size:17px; line-height:1.7; color:var(--text); font-weight:600; margin-bottom:18px; max-width:1100px; }
  .value-title b{ color:var(--gold-dim); }
  .value-banner{
    background:linear-gradient(90deg, var(--navy), var(--navy-dark)); color:#fff; font-family:'Noto Sans Thai'; font-weight:600;
    font-size:14.5px; padding:14px 22px; border-radius:12px; margin-bottom:18px;
  }
  .value-top-grid{ display:grid; grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr); gap:18px; margin-bottom:18px; }
  .value-total-card{
    background:linear-gradient(135deg, var(--navy), var(--navy-dark)); border-radius:16px; padding:24px 24px 18px; color:#fff;
    display:flex; flex-direction:column; gap:14px; box-shadow:0 4px 18px rgba(15,42,107,0.25);
  }
  .value-total-top{ display:flex; align-items:center; gap:16px; }
  .value-icon-circle{
    width:56px; height:56px; border-radius:50%; background:rgba(255,255,255,0.12); display:flex; align-items:center; justify-content:center;
    font-size:26px; flex-shrink:0;
  }
  .value-total-label{ font-size:13px; color:rgba(255,255,255,0.75); font-family:'Noto Sans Thai'; }
  .value-total-num{ font-family:'Noto Sans Thai'; font-weight:800; font-size:40px; margin-top:2px; display:flex; align-items:baseline; gap:10px; }
  .value-total-num .unit{ font-size:14px; font-weight:400; color:rgba(255,255,255,0.7); }
  .value-total-trend{ font-family:'Noto Sans Thai'; font-weight:700; font-size:13px; color:#7CE0C8; display:flex; align-items:center; gap:5px; }
  .value-stat-row{ display:flex; gap:0; border-top:1px solid rgba(255,255,255,0.15); padding-top:14px; }
  .value-stat{ flex:1; }
  .value-stat + .value-stat{ border-left:1px solid rgba(255,255,255,0.15); padding-left:16px; margin-left:16px; }
  .value-stat .label{ font-size:12px; color:rgba(255,255,255,0.65); font-family:'Noto Sans Thai'; margin-bottom:4px; }
  .value-stat .num{ font-family:'Noto Sans Thai'; font-weight:700; font-size:22px; }
  .value-stat .num .unit{ font-size:12px; font-weight:400; color:rgba(255,255,255,0.65); margin-left:3px; }
  .value-stat .trend{ font-size:11.5px; color:#7CE0C8; margin-top:3px; font-family:'Noto Sans Thai'; }

  .value-right-card{
    background:var(--card); border:1px solid var(--border-soft); border-radius:16px; padding:22px 24px;
    display:grid; grid-template-columns:180px 1fr; gap:20px; align-items:center; box-shadow:0 2px 14px rgba(20,33,61,0.05);
  }
  .value-donut-wrap{ position:relative; width:180px; height:180px; }
  .value-donut-center{ position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-size:30px; }
  .value-struct-title{ font-family:'Noto Sans Thai'; font-weight:600; font-size:13.5px; color:var(--text); margin-bottom:12px; }
  .value-struct-row{ display:flex; align-items:center; gap:10px; margin-bottom:10px; }
  .value-struct-row:last-child{ margin-bottom:0; }
  .value-struct-legend{ display:flex; align-items:center; gap:6px; width:64px; font-size:12px; color:var(--text-mid); font-family:'Noto Sans Thai'; flex-shrink:0; }
  .value-struct-legend .dot{ width:9px; height:9px; border-radius:3px; flex-shrink:0; }
  .value-struct-bars{ flex:1; display:flex; flex-direction:column; gap:3px; }
  .value-struct-bar-track{ display:flex; align-items:center; gap:8px; }
  .value-struct-bar-track .bar{ height:9px; border-radius:5px; }
  .value-struct-bar-track .bar.old{ background:rgba(20,33,61,0.14); }
  .value-struct-bar-track .val{ font-size:11px; font-family:'Noto Sans Thai'; color:var(--text-mid); width:36px; }
  .value-struct-yoy{ font-size:11px; font-family:'Noto Sans Thai'; font-weight:700; color:var(--teal); white-space:nowrap; flex-shrink:0; }

  .value-connector{
    text-align:center; background:linear-gradient(90deg, var(--navy), var(--navy-dark)); color:#fff; font-family:'Noto Sans Thai';
    font-weight:600; font-size:13px; padding:10px 20px; border-radius:20px; max-width:620px; margin:0 auto 20px;
  }
  .value-breakdown-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:16px; }
  .value-breakdown-card{ background:var(--card); border:1px solid var(--border-soft); border-radius:14px; overflow:hidden; box-shadow:0 2px 14px rgba(20,33,61,0.05); }
  .value-breakdown-head{ color:#fff; font-family:'Noto Sans Thai'; font-weight:700; font-size:15px; text-align:center; padding:12px; }
  .value-breakdown-body{ padding:20px 22px; display:flex; flex-direction:column; align-items:center; text-align:center; gap:10px; }
  .value-breakdown-icon{ font-size:34px; }
  .value-breakdown-body .sub-label{ font-size:12px; color:var(--text-dim); font-family:'Noto Sans Thai'; }
  .value-breakdown-body .sub-value{ font-family:'Noto Sans Thai'; font-weight:700; font-size:22px; color:var(--text); }
  .value-breakdown-body .sub-value .unit{ font-size:12px; font-weight:400; color:var(--text-mid); margin-left:3px; }
  .value-breakdown-divider{ width:100%; height:1px; background:var(--border-soft); margin:2px 0; }
  .value-note{ font-size:11px; color:var(--text-dim); font-family:'Noto Sans Thai'; margin-top:14px; text-align:right; }

  @media(max-width:900px){
    .value-top-grid{ grid-template-columns:1fr; }
    .value-right-card{ grid-template-columns:1fr; justify-items:center; }
    .value-breakdown-grid{ grid-template-columns:1fr; }
  }

  /* ---- Channel value charts (static, report-sourced) ---- */
  .chanval-grid{ display:grid; grid-template-columns:minmax(0,0.9fr) minmax(0,1.1fr); gap:18px; }
  .chanval-card{ background:var(--card); border:1px solid var(--border-soft); border-radius:16px; padding:22px 24px; box-shadow:0 2px 14px rgba(20,33,61,0.05); }
  .chanval-card h3{ font-size:14px; font-weight:600; color:var(--text); margin-bottom:2px; }
  .chanval-card .hint{ font-size:11.5px; color:var(--text-dim); margin-bottom:14px; font-family:'Noto Sans Thai'; }
  .chanval-donut-wrap{ position:relative; width:220px; height:220px; margin:0 auto; }
  .chanval-donut-center{ position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; }
  .chanval-donut-center .num{ font-family:'Noto Sans Thai'; font-weight:800; font-size:28px; color:var(--text); }
  .chanval-donut-center .unit{ font-size:11.5px; color:var(--text-dim); font-family:'Noto Sans Thai'; }
  .chanval-donut-center .trend{ font-size:10.5px; color:var(--teal); font-weight:700; margin-top:4px; font-family:'Noto Sans Thai'; background:rgba(15,168,154,0.12); padding:2px 8px; border-radius:10px; }
  .chanval-legend{ display:flex; flex-wrap:wrap; justify-content:center; gap:8px 18px; margin-top:16px; }
  .chanval-legend .item{ display:flex; align-items:center; gap:6px; font-size:12px; color:var(--text-mid); font-family:'Noto Sans Thai'; }
  .chanval-legend .dot{ width:9px; height:9px; border-radius:3px; flex-shrink:0; }
  .chanval-legend .item b{ color:var(--text); }
  .chanval-bar-wrap{ height:280px; }
  .chanval-yoy-row{ display:flex; justify-content:space-around; margin-top:10px; }
  .chanval-yoy-row .item{ font-size:11px; font-family:'Noto Sans Thai'; font-weight:700; color:var(--teal); text-align:center; }

  @media(max-width:900px){
    .chanval-grid{ grid-template-columns:1fr; }
  }


  @media(max-width:900px){
    .filter-cluster{width:100%; border-radius:14px; padding:10px 14px;}
    .topbar .flabel{width:100%;}
    .app-shell{flex-direction:column;}
    .sidebar{
      width:100%; height:auto; position:sticky; top:var(--topbar-h); z-index:60;
      border-bottom:1px solid rgba(255,255,255,0.08);
      flex-direction:row; align-items:center; padding:10px 16px; gap:14px;
    }
    .sidenav{flex-direction:row; flex-wrap:wrap; overflow-x:auto; gap:4px;}
    .sidenav a{white-space:nowrap; padding:6px 10px;}
    .kpi-row{grid-template-columns:repeat(2,1fr);}
    .grid2, .grid2-even, .grid3, .grid4, .circle-row{grid-template-columns:1fr;}
    .dmi-hero{grid-template-columns:1fr;}
    .fcount{margin-left:0; width:100%; text-align:center;}
  }
`;
