/* =========================================================
   INIT
   ========================================================= */
function populateSelect(id, options){
  const sel = document.getElementById(id);
  const currentValue = sel.value;
  // keep only the first static "All" option, remove any previously-populated ones
  while(sel.options.length > 1) sel.remove(1);
  options.forEach((name, idx)=>{
    const opt = document.createElement('option');
    opt.value = idx; opt.textContent = name;
    sel.appendChild(opt);
  });
  sel.value = currentValue;
}

function initScrollSpy(){
  const links = document.querySelectorAll('.sidenav a');
  const map = {};
  links.forEach(a=>{ const id = a.getAttribute('href').slice(1); map[id] = a; });
  const targets = Object.keys(map).map(id=>document.getElementById(id)).filter(Boolean);
  if(!targets.length || typeof IntersectionObserver === 'undefined') return;
  const setActive = (id)=>{
    Object.values(map).forEach(a=>a.classList.remove('active'));
    if(map[id]) map[id].classList.add('active');
  };
  const observer = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting) setActive(entry.target.id);
    });
  }, { rootMargin:'-15% 0px -70% 0px', threshold:0 });
  targets.forEach(t=>observer.observe(t));
  setActive(targets[0].id);
}

function bindFilters(){
  document.getElementById('fRegion').addEventListener('change', e=>{ state.region = parseInt(e.target.value); renderAll(); });
  document.getElementById('fUrban').addEventListener('change', e=>{ state.urban = parseInt(e.target.value); renderAll(); });
  document.getElementById('fGen').addEventListener('change', e=>{ state.gen = parseInt(e.target.value); renderAll(); });
  document.getElementById('fReg').addEventListener('change', e=>{ state.reg = parseInt(e.target.value); renderAll(); });
  document.getElementById('fReset').addEventListener('click', ()=>{
    state.region=-1; state.urban=-1; state.gen=-1; state.reg=-1;
    document.getElementById('fRegion').value=-1;
    document.getElementById('fUrban').value=-1;
    document.getElementById('fGen').value=-1;
    document.getElementById('fReg').value=-1;
    renderAll();
  });
}

function syncLayoutOffsets(){
  const topbarEl = document.querySelector('.topbar');
  if(!topbarEl) return;
  const th = topbarEl.offsetHeight;
  if(th > 0) document.documentElement.style.setProperty('--topbar-h', th + 'px');
}

function initLangStatic(){
  document.querySelectorAll('.i18n').forEach(el=>{
    if(!el.hasAttribute('data-th')) el.setAttribute('data-th', el.textContent);
  });
  document.querySelectorAll('option[data-en]').forEach(el=>{
    if(!el.hasAttribute('data-th')) el.setAttribute('data-th', el.textContent);
  });
  document.querySelectorAll('[data-en-html]').forEach(el=>{
    if(!el.hasAttribute('data-th-html')) el.setAttribute('data-th-html', el.innerHTML);
  });
}

function applyLang(lang){
  state.lang = lang;
  document.documentElement.setAttribute('lang', lang);
  document.querySelectorAll('.lang-btn').forEach(b=>{
    const isActive = b.getAttribute('data-lang')===lang;
    b.classList.toggle('active', isActive);
    b.style.background = isActive ? '#fff' : 'none';
    b.style.color = isActive ? '#1A2233' : '#8891A0';
    b.style.fontWeight = isActive ? '800' : '700';
    b.style.boxShadow = isActive ? '0 1px 4px rgba(20,33,61,0.12), 0 0 0 1px rgba(20,33,61,0.03)' : 'none';
  });
  document.querySelectorAll('.i18n').forEach(el=>{
    el.textContent = lang==='en' ? el.getAttribute('data-en') : el.getAttribute('data-th');
  });
  document.querySelectorAll('option[data-en]').forEach(el=>{
    el.textContent = lang==='en' ? el.getAttribute('data-en') : el.getAttribute('data-th');
  });
  document.querySelectorAll('[data-en-html]').forEach(el=>{
    el.innerHTML = lang==='en' ? el.getAttribute('data-en-html') : el.getAttribute('data-th-html');
  });
  populateSelect('fRegion', L('REGIONS'));
  populateSelect('fGen', L('GENS'));
  renderLevelLegend('dmiLevelLegend');
  renderValueDonut();
  renderChannelValueCharts();
  renderAll();
}

function initLangToggle(){
  initLangStatic();
  document.querySelectorAll('.lang-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const lang = btn.getAttribute('data-lang');
      if(lang!==state.lang) applyLang(lang);
    });
  });
}

function initDashboard(){
  Chart.register(ChartDataLabels);
  Chart.defaults.font.family = baseFont();
  Chart.defaults.color = C.textMid;
  Chart.defaults.font.size = 11.5;
  Chart.defaults.plugins.datalabels = Chart.defaults.plugins.datalabels || {};
  Chart.defaults.plugins.datalabels.display = false;

  ROWS = DATA.records;
  LOOKUPS = DATA.lookups;

  document.getElementById('logoImg').src = 'data:image/png;base64,' + LOGO_B64;

  populateSelect('fRegion', L('REGIONS'));
  populateSelect('fGen', L('GENS'));
  renderLevelLegend('dmiLevelLegend');
  renderValueDonut();
  renderChannelValueCharts();
  bindFilters();
  bindDmiScatterToggle();
  renderAll();
  initScrollSpy();
  initLangToggle();

  syncLayoutOffsets();
  window.addEventListener('resize', syncLayoutOffsets);
  if(document.fonts && document.fonts.ready){ document.fonts.ready.then(syncLayoutOffsets); }
}

